#!/usr/bin/env bash# =============================================================================#  Create the IAM user the screenshot automation needs.##      bash create-evidence-user.sh              # user + keys + sign-in URL#      bash create-evidence-user.sh --console    # also give it a console password#      bash create-evidence-user.sh --delete     # remove it when you are done##  Run this in AWS CloudShell. It cannot take the screenshots itself -#  CloudShell has no browser - but it creates everything the local#  scripts\capture-evidence.ps1 run needs, and prints that command filled in.##  Why an IAM user at all: root credentials cannot call#  sts:GetFederationToken, which is what turns credentials into a console#  sign-in URL. That is an AWS restriction, not a preference.# =============================================================================set -euo pipefailREGION="${REGION:-us-east-1}"IAM_USER="${IAM_USER:-evidence-capture}"export AWS_DEFAULT_REGION="$REGION"if [ -t 1 ]; then  H=$'\033[1;36m'; G=$'\033[0;32m'; Y=$'\033[0;33m'; R=$'\033[0;31m'; O=$'\033[0m'else H=""; G=""; Y=""; R=""; O=""; fistep() { printf '\n%s━━━ %s%s\n' "$H" "$*" "$O"; }ok()   { printf '     %s✓%s %s\n' "$G" "$O" "$*"; }warn() { printf '     %s!%s %s\n' "$Y" "$O" "$*"; }die()  { printf '\n%s✗ %s%s\n' "$R" "$*" "$O" >&2; exit 1; }WANT_CONSOLE=0if [ "${1:-}" = "--console" ]; then WANT_CONSOLE=1; fi# --------------------------------------------------------------- delete -----if [ "${1:-}" = "--delete" ]; then  step "Removing $IAM_USER"  for k in $(aws iam list-access-keys --user-name "$IAM_USER" \               --query 'AccessKeyMetadata[].AccessKeyId' --output text 2>/dev/null); do    aws iam delete-access-key --user-name "$IAM_USER" --access-key-id "$k"    ok "deleted key $k"  done  aws iam delete-login-profile --user-name "$IAM_USER" 2>/dev/null && ok "console password removed" || true  for pol in AllowConsoleFederation AllowEvidenceUpload; do    aws iam delete-user-policy --user-name "$IAM_USER" --policy-name "$pol" 2>/dev/null || true  done  aws iam detach-user-policy --user-name "$IAM_USER" \    --policy-arn arn:aws:iam::aws:policy/ReadOnlyAccess 2>/dev/null || true  aws iam delete-user --user-name "$IAM_USER" && ok "user deleted"  echo; echo "Done. Also delete the local .evidence-capture-key.json."  exit 0fi# ------------------------------------------------------------- preflight ----step "Preflight"command -v aws >/dev/null || die "aws CLI not found (unexpected in CloudShell)."ACCOUNT="$(aws sts get-caller-identity --query Account --output text)" || die "No credentials."CALLER="$(aws sts get-caller-identity --query Arn --output text)"ok "account $ACCOUNT · region $REGION"ok "$CALLER"case "$CALLER" in  *:root) warn "running as root - which is exactly why this user is needed" ;;esac# ------------------------------------------------------------------ user ----step "IAM user: $IAM_USER"if aws iam get-user --user-name "$IAM_USER" >/dev/null 2>&1; then  ok "already exists"else  aws iam create-user --user-name "$IAM_USER" >/dev/null  ok "created"fi# Read access to everything the console pages need: Bedrock, DynamoDB,# Lambda, CloudWatch, CloudFormation.aws iam attach-user-policy --user-name "$IAM_USER" \  --policy-arn arn:aws:iam::aws:policy/ReadOnlyAccessok "ReadOnlyAccess attached"# ReadOnlyAccess does not include GetFederationToken - it is not a read# action - so it is granted explicitly.aws iam put-user-policy --user-name "$IAM_USER" \  --policy-name AllowConsoleFederation \  --policy-document '{    "Version": "2012-10-17",    "Statement": [{      "Sid": "ConsoleFederation",      "Effect": "Allow",      "Action": "sts:GetFederationToken",      "Resource": "*"    }]  }'ok "sts:GetFederationToken allowed"# The screenshots are uploaded next to the evaluation results. This is the# only write the user gets: PutObject, on the evidence/ prefix of the# evaluation bucket, and nothing else.aws iam put-user-policy --user-name "$IAM_USER"   --policy-name AllowEvidenceUpload   --policy-document "{    \"Version\": \"2012-10-17\",    \"Statement\": [{      \"Sid\": \"UploadScreenshots\",      \"Effect\": \"Allow\",      \"Action\": \"s3:PutObject\",      \"Resource\": \"arn:aws:s3:::udacity-agentic-engineer-c1-eval-${ACCOUNT}/evidence/*\"    }]  }"ok "s3:PutObject allowed on the evidence/ prefix only"# --------------------------------------------------------------- console ----if [ "$WANT_CONSOLE" = "1" ]; then  step "Console password"  PW="$(python3 -c "import secrets, stringalphabet = string.ascii_letters + string.digits + '!@#\$%^&*()-_=+'print(''.join(secrets.choice(alphabet) for _ in range(24)))")"  if aws iam create-login-profile --user-name "$IAM_USER" \       --password "$PW" --no-password-reset-required >/dev/null 2>&1; then    ok "console password created"    CONSOLE_PW="$PW"  else    warn "a login profile already exists - leaving it alone"    CONSOLE_PW=""  fifi# ------------------------------------------------------------------ keys ----step "Access key"COUNT="$(aws iam list-access-keys --user-name "$IAM_USER" \          --query 'length(AccessKeyMetadata)' --output text)"if [ "$COUNT" -ge 2 ]; then  warn "this user already has 2 keys (the AWS maximum)."  warn "delete one and re-run, or reuse the key you already saved."  ACCESS_KEY_ID=""; SECRET_KEY=""else  CREATED="$(aws iam create-access-key --user-name "$IAM_USER" \              --query 'AccessKey.[AccessKeyId,SecretAccessKey]' --output text)"  ACCESS_KEY_ID="$(echo "$CREATED" | awk '{print $1}')"  SECRET_KEY="$(echo "$CREATED" | awk '{print $2}')"  ok "created $ACCESS_KEY_ID"  echo "     waiting 10s for IAM to propagate..."  sleep 10fi# -------------------------------------------------------- sign-in URL -------step "Console sign-in URL"if [ -n "$ACCESS_KEY_ID" ]; then  SIGNIN_URL="$(    AWS_ACCESS_KEY_ID="$ACCESS_KEY_ID" \    AWS_SECRET_ACCESS_KEY="$SECRET_KEY" \    AWS_SESSION_TOKEN="" \    python3 - "$REGION" <<'PYFED'import json, sys, urllib.parse, urllib.requestimport boto3region = sys.argv[1]creds = boto3.client("sts").get_federation_token(    Name="evidence-capture",    Policy=json.dumps({"Version": "2012-10-17",                       "Statement": [{"Effect": "Allow",                                      "Action": "*", "Resource": "*"}]}),    DurationSeconds=3600,)["Credentials"]session = urllib.parse.quote(json.dumps({    "sessionId": creds["AccessKeyId"],    "sessionKey": creds["SecretAccessKey"],    "sessionToken": creds["SessionToken"],}))token = json.load(urllib.request.urlopen(    f"https://signin.aws.amazon.com/federation?Action=getSigninToken&Session={session}"))["SigninToken"]dest = urllib.parse.quote(    f"https://{region}.console.aws.amazon.com/console/home?region={region}")print("https://signin.aws.amazon.com/federation?Action=login"      f"&Issuer=evidence-capture&Destination={dest}&SigninToken={token}")PYFED  )" || SIGNIN_URL=""  [ -n "$SIGNIN_URL" ] && ok "minted (valid ~1 hour)" || warn "could not mint a URL"else  SIGNIN_URL=""fi# ------------------------------------------------------------------ out -----cat <<BANNER${H}================================================================${O}  NEXT: run this on your own machine, in PowerShell, from the repo${H}================================================================${O}BANNERif [ -n "$ACCESS_KEY_ID" ]; thencat <<PSCMD  \$env:AWS_ACCESS_KEY_ID     = "$ACCESS_KEY_ID"  \$env:AWS_SECRET_ACCESS_KEY = "$SECRET_KEY"  \$env:AWS_DEFAULT_REGION    = "$REGION"  .\\scripts\\capture-evidence.ps1 -FederatedPSCMDcat <<'ENVNOTE'  Or put the same two values in .env (it is git-ignored) so you do not  have to paste them again.ENVNOTEelsecat <<'NOKEY'  No new key was created. Use the key you saved earlier, or delete one:    aws iam list-access-keys --user-name evidence-capture    aws iam delete-access-key --user-name evidence-capture --access-key-id <OLD>NOKEYfiif [ "${WANT_CONSOLE:-0}" = "1" ] && [ -n "${CONSOLE_PW:-}" ]; thencat <<CONSOLEINFO  Console sign-in for this user (use instead of root from now on):    https://${ACCOUNT}.signin.aws.amazon.com/console    username: $IAM_USER    password: $CONSOLE_PWCONSOLEINFOfiif [ -n "$SIGNIN_URL" ]; thencat <<URLINFO  One-click console sign-in, no password (expires in ~1 hour):$SIGNIN_URLURLINFOficat <<'SECURITY'  ----------------------------------------------------------------  The secret above is shown ONCE and is a real credential.  Copy it, then wipe this terminal:      clear && history -c  This user is read-only: it can view the console but cannot change  or delete anything. Remove it when you are finished:      bash create-evidence-user.sh --delete  ----------------------------------------------------------------SECURITY